SAFE_SOURCE='import os\nfrom pathlib import Path\nimport re\nimport stat\nimport time\n\nMAX_JSON_BYTES=1048576\nARTIFACT_NAMES=("sdk-image-scan-receipt.json",)\nSIDECAR_NAMES=("producer.exit",)\n\nclass ArtifactRejected(Exception):\n    """Fixed private failure with no input content or filesystem path."""\n\ndef require(value):\n    if not value:\n        raise ArtifactRejected()\n\ndef closed(value, keys):\n    require(type(value) is dict and set(value) == set(keys))\n\ndef integer(value, low, high):\n    require(type(value) is int and low <= value <= high)\n    return value\n\ndef metadata(info):\n    return (info.st_dev,info.st_ino,info.st_mode,info.st_uid,info.st_gid,info.st_nlink,\n            info.st_size,info.st_mtime_ns,info.st_ctime_ns)\n\ndef read_file(directory_fd, name, cap, directory_device, host_uid, deadline):\n    require(name in ARTIFACT_NAMES+SIDECAR_NAMES and \'/\' not in name)\n    require(time.monotonic() < deadline)\n    try:\n        before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)\n    except FileNotFoundError:\n        return None\n    require(stat.S_ISREG(before.st_mode) and before.st_nlink == 1 and before.st_uid == host_uid and\n            before.st_dev == directory_device and stat.S_IMODE(before.st_mode) == 0o600 and\n            0 < before.st_size <= cap)\n    fd = os.open(name, os.O_RDONLY|os.O_NONBLOCK|os.O_NOFOLLOW|os.O_CLOEXEC, dir_fd=directory_fd)\n    try:\n        require(metadata(os.fstat(fd)) == metadata(before))\n        chunks = []; count = 0\n        while True:\n            require(time.monotonic() < deadline)\n            raw = os.read(fd, min(65536,cap+1-count))\n            if not raw: break\n            count += len(raw); require(count <= cap); chunks.append(raw)\n        after = os.fstat(fd)\n        require(metadata(after) == metadata(before) and count == before.st_size)\n        require(metadata(os.stat(name,dir_fd=directory_fd,follow_symlinks=False)) == metadata(before))\n        return {\'raw\':b\'\'.join(chunks),\'metadata\':metadata(before)}\n    finally:\n        os.close(fd)\n\ndef exit_code(raw):\n    require(type(raw) is bytes and re.fullmatch(rb\'(?:0|[1-9][0-9]{0,2})\\n?\',raw) is not None)\n    return integer(int(raw),0,255)\n\ndef present_names(directory_fd):\n    result = set()\n    with os.scandir(directory_fd) as entries:\n        for entry in entries:\n            require(len(result) < len(ARTIFACT_NAMES)+len(SIDECAR_NAMES) and entry.name in ARTIFACT_NAMES+SIDECAR_NAMES)\n            result.add(entry.name)\n    return result\n\ndef check_safe_artifacts(*, report_dir, source_root, created_identity, step_outcome):\n    """Producer-only allowlist. Caller must preserve any failed job independently."""\n    denied = {\'status\':\'REJECTED_SAFE_ARTIFACT_INPUT\',\'has-artifacts\':False,\n              \'artifact_names\':[],\'qualification_passed\':False}\n    directory_fd = None\n    deadline = time.monotonic()+15\n    try:\n        require(type(step_outcome) is str and step_outcome in (\'success\',\'failure\',\'skipped\',\'cancelled\'))\n        closed(created_identity,(\'device\',\'inode\',\'uid\'))\n        integer(created_identity[\'device\'],0,2**63-1); integer(created_identity[\'inode\'],1,2**63-1)\n        integer(created_identity[\'uid\'],os.geteuid(),os.geteuid())\n        report_dir,source_root = Path(report_dir),Path(source_root)\n        require(report_dir.is_absolute() and report_dir.resolve(strict=True) == report_dir and\n                source_root.is_absolute() and source_root.resolve(strict=True) == source_root and source_root.is_dir() and\n                not report_dir.is_relative_to(source_root))\n        before = report_dir.lstat(); host_uid = os.geteuid()\n        require(stat.S_ISDIR(before.st_mode) and stat.S_IMODE(before.st_mode) == 0o700 and before.st_uid == host_uid and\n                (before.st_dev,before.st_ino,before.st_uid) ==\n                (created_identity[\'device\'],created_identity[\'inode\'],created_identity[\'uid\']))\n        directory_fd = os.open(report_dir,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_CLOEXEC)\n        require(metadata(os.fstat(directory_fd)) == metadata(before) and time.monotonic() < deadline)\n        present = present_names(directory_fd)\n        report_name,exit_name = ARTIFACT_NAMES[0],SIDECAR_NAMES[0]\n        snapshots = {name:read_file(directory_fd,name,4 if name == exit_name else MAX_JSON_BYTES,\n                                   before.st_dev,host_uid,deadline)\n                     for name in ARTIFACT_NAMES+SIDECAR_NAMES}\n        item,side = snapshots[report_name],snapshots[exit_name]\n        allowed = []; qualified = False\n        if step_outcome == \'skipped\':\n            require(item is None and side is None)\n        else:\n            actual_exit = None if side is None else exit_code(side[\'raw\'])\n            if item is None:\n                require(step_outcome in (\'failure\',\'cancelled\') and actual_exit != 0)\n            else:\n                require(actual_exit is not None)\n                decoded = VALIDATE_SAFE_SUMMARY(item[\'raw\'])\n                require(type(decoded) is dict and set(decoded) == {\'valid\',\'report\'} and decoded[\'valid\'] is True)\n                passed = decoded[\'report\'][\'status\'] == \'PASS\'\n                if passed:\n                    # A PASS file never overrides the actual command or GitHub outcome.\n                    require(actual_exit == 0 and step_outcome == \'success\')\n                else:\n                    require(1 <= actual_exit <= 255 and step_outcome in (\'failure\',\'cancelled\'))\n                allowed.append(report_name); qualified = passed\n        # Recheck names, full metadata and path identity AFTER all parsing/validation.\n        require(time.monotonic() < deadline and present_names(directory_fd) == present and\n                metadata(os.fstat(directory_fd)) == metadata(before) and\n                report_dir.resolve(strict=True) == report_dir and metadata(report_dir.lstat()) == metadata(before))\n        for name,item in snapshots.items():\n            try: current = os.stat(name,dir_fd=directory_fd,follow_symlinks=False)\n            except FileNotFoundError:\n                require(item is None)\n            else:\n                require(item is not None and metadata(current) == item[\'metadata\'])\n        require(time.monotonic() < deadline)\n        return {\'status\':\'CHECKED_SAFE_ARTIFACT_ALLOWLIST_ONLY\',\'has-artifacts\':bool(allowed),\n                \'artifact_names\':allowed,\'qualification_passed\':qualified}\n    except (ArtifactRejected,OSError,ValueError,TypeError,KeyError,UnicodeError,RecursionError,OverflowError):\n        return denied\n    finally:\n        if directory_fd is not None: os.close(directory_fd)\n\n'
